const STORAGE_KEYS = {
  projects: "shipkit-projects",
  projectMembers: "shipkit-project-members",
  teams: "shipkit-teams",
  teamMembers: "shipkit-team-members",
  users: "shipkit-users",
} as const;

// Local storage utility functions
const isClient = typeof window !== "undefined";

function getFromStorage<T>(key: string): T[] {
  if (!isClient) return [];
  try {
    const data = localStorage.getItem(key);
    if (!data) return [];
    const parsed = JSON.parse(data);
    // Convert date strings back to Date objects
    return parsed.map((item: any) => ({
      ...item,
      createdAt: item.createdAt ? new Date(item.createdAt) : new Date(),
      updatedAt: item.updatedAt ? new Date(item.updatedAt) : new Date(),
      deletedAt: item.deletedAt ? new Date(item.deletedAt) : null,
    }));
  } catch (error) {
    console.warn(`Error parsing localStorage key "${key}":`, error);
    return [];
  }
}

function saveToStorage<T>(key: string, data: T[]): void {
  if (!isClient) return;
  try {
    localStorage.setItem(key, JSON.stringify(data));
  } catch (error) {
    console.warn(`Error saving to localStorage key "${key}":`, error);
  }
}

export class LocalProjectStorage {
  /**
   * Creates a new project in local storage
   */
  static createProject(teamId: string, projectName: string, creatorUserId: string): LocalProject {
    const projectId = crypto.randomUUID();
    const now = new Date();

    // Create project
    const project: LocalProject = {
      id: projectId,
      name: projectName,
      teamId,
      createdAt: now,
      updatedAt: now,
      members: [],
    };

    // Create project member
    const member: LocalProjectMember = {
      id: crypto.randomUUID(),
      projectId,
      userId: creatorUserId,
      role: "owner",
      createdAt: now,
      updatedAt: now,
      user: LocalProjectStorage.getUserFromStorage(creatorUserId),
    };

    // Save to storage
    const projects = getFromStorage<LocalProject>(STORAGE_KEYS.projects);
    projects.push(project);
    saveToStorage(STORAGE_KEYS.projects, projects);

    const projectMembers = getFromStorage<LocalProjectMember>(STORAGE_KEYS.projectMembers);
    projectMembers.push(member);
    saveToStorage(STORAGE_KEYS.projectMembers, projectMembers);

    // Return project with members
    project.members = [member];
    return project;
  }

  /**
   * Gets all projects for a team
   */
  static getTeamProjects(teamId: string): LocalProject[] {
    const projects = getFromStorage<LocalProject>(STORAGE_KEYS.projects);
    const projectMembers = getFromStorage<LocalProjectMember>(STORAGE_KEYS.projectMembers);

    return projects
      .filter((p) => p.teamId === teamId)
      .map((project) => ({
        ...project,
        members: projectMembers.filter((m) => m.projectId === project.id),
      }));
  }

  /**
   * Updates a project
   */
  static updateProject(projectId: string, projectName: string): LocalProject | null {
    const projects = getFromStorage<LocalProject>(STORAGE_KEYS.projects);
    const projectIndex = projects.findIndex((p) => p.id === projectId);

    if (projectIndex === -1) return null;

    const existingProject = projects[projectIndex];
    if (!existingProject) return null;

    projects[projectIndex] = {
      ...existingProject,
      name: projectName,
      updatedAt: new Date(),
      id: existingProject.id || "",
      teamId: existingProject.teamId || "",
      createdAt: existingProject.createdAt || new Date(),
      members: existingProject.members || [],
    };

    saveToStorage(STORAGE_KEYS.projects, projects);

    // Return with members
    const projectMembers = getFromStorage<LocalProjectMember>(STORAGE_KEYS.projectMembers);
    const updatedProject = projects[projectIndex];
    return {
      ...updatedProject,
      id: updatedProject.id || "",
      name: updatedProject.name || "",
      teamId: updatedProject.teamId || "",
      createdAt: updatedProject.createdAt || new Date(),
      updatedAt: updatedProject.updatedAt || new Date(),
      members: projectMembers.filter((m) => m.projectId === projectId),
    };
  }

  /**
   * Deletes a project
   */
  static deleteProject(projectId: string): boolean {
    const projects = getFromStorage<LocalProject>(STORAGE_KEYS.projects);
    const projectMembers = getFromStorage<LocalProjectMember>(STORAGE_KEYS.projectMembers);

    // Remove project
    const filteredProjects = projects.filter((p) => p.id !== projectId);
    saveToStorage(STORAGE_KEYS.projects, filteredProjects);

    // Remove project members
    const filteredMembers = projectMembers.filter((m) => m.projectId !== projectId);
    saveToStorage(STORAGE_KEYS.projectMembers, filteredMembers);

    return true;
  }

  /**
   * Adds a member to a project
   */
  static addProjectMember(projectId: string, userId: string, role: string): LocalProjectMember {
    const projectMembers = getFromStorage<LocalProjectMember>(STORAGE_KEYS.projectMembers);

    const member: LocalProjectMember = {
      id: crypto.randomUUID(),
      projectId,
      userId,
      role,
      createdAt: new Date(),
      updatedAt: new Date(),
      user: LocalProjectStorage.getUserFromStorage(userId),
    };

    projectMembers.push(member);
    saveToStorage(STORAGE_KEYS.projectMembers, projectMembers);

    return member;
  }

  /**
   * Removes a member from a project
   */
  static removeProjectMember(projectId: string, userId: string): boolean {
    const projectMembers = getFromStorage<LocalProjectMember>(STORAGE_KEYS.projectMembers);
    const filteredMembers = projectMembers.filter(
      (m) => !(m.projectId === projectId && m.userId === userId)
    );

    saveToStorage(STORAGE_KEYS.projectMembers, filteredMembers);
    return filteredMembers.length !== projectMembers.length;
  }

  /**
   * Updates a project member's role
   */
  static updateProjectMemberRole(
    projectId: string,
    userId: string,
    role: string
  ): LocalProjectMember | null {
    const projectMembers = getFromStorage<LocalProjectMember>(STORAGE_KEYS.projectMembers);
    const memberIndex = projectMembers.findIndex(
      (m) => m.projectId === projectId && m.userId === userId
    );

    if (memberIndex === -1) return null;

    const existingMember = projectMembers[memberIndex];
    if (!existingMember) return null;

    projectMembers[memberIndex] = {
      ...existingMember,
      role,
      updatedAt: new Date(),
      id: existingMember.id || "",
      projectId: existingMember.projectId || "",
      userId: existingMember.userId || "",
      createdAt: existingMember.createdAt || new Date(),
      user: existingMember.user || undefined,
    };

    saveToStorage(STORAGE_KEYS.projectMembers, projectMembers);
    return projectMembers[memberIndex];
  }

  /**
   * Gets project members
   */
  static getProjectMembers(projectId: string): LocalProjectMember[] {
    const projectMembers = getFromStorage<LocalProjectMember>(STORAGE_KEYS.projectMembers);
    return projectMembers.filter((m) => m.projectId === projectId);
  }

  /**
   * Checks if user has access to project
   */
  static userHasAccessToProject(userId: string, projectId: string): boolean {
    const projectMembers = getFromStorage<LocalProjectMember>(STORAGE_KEYS.projectMembers);
    return projectMembers.some((m) => m.userId === userId && m.projectId === projectId);
  }

  /**
   * Helper to get user data from storage (fallback for demo purposes)
   */
  private static getUserFromStorage(userId: string): {
    id: string;
    name: string | null;
    email: string;
  } {
    // In a real implementation, you'd store user data separately
    // For now, return a basic structure
    return {
      id: userId,
      name: `User ${userId.slice(0, 8)}`,
      email: `user-${userId.slice(0, 8)}@example.com`,
    };
  }

  /**
   * Initialize with demo data if storage is empty
   */
  static initializeDemoData(userId: string, teamId: string): void {
    const projects = getFromStorage<LocalProject>(STORAGE_KEYS.projects);

    if (projects.length === 0) {
      // Create a demo project
      LocalProjectStorage.createProject(teamId, "Demo Project", userId);
    }
  }

  /**
   * Clear all project data from localStorage
   */
  static clearAll(): void {
    if (!isClient) return;

    localStorage.removeItem(STORAGE_KEYS.projects);
    localStorage.removeItem(STORAGE_KEYS.projectMembers);
  }
}

export interface LocalTeam {
  id: string;
  name: string;
  type: "personal" | "workspace";
  createdAt: Date;
  updatedAt: Date | null;
  deletedAt: Date | null;
}

export interface LocalTeamMember {
  id: string;
  teamId: string;
  userId: string;
  role: string;
  createdAt: Date;
  updatedAt: Date;
  user: {
    id: string;
    name: string | null;
    email: string;
  };
}

export interface LocalUser {
  id: string;
  name: string | null;
  email: string;
  createdAt: Date;
  updatedAt: Date;
}

const STORAGE_KEYS = {
  teams: "shipkit-teams",
  teamMembers: "shipkit-team-members",
  users: "shipkit-users",
} as const;

// Local storage utility functions
const isClient = typeof window !== "undefined";

function getFromStorage<T>(key: string): T[] {
  if (!isClient) return [];
  try {
    const data = localStorage.getItem(key);
    if (!data) return [];
    const parsed = JSON.parse(data);
    // Convert date strings back to Date objects
    return parsed.map((item: any) => ({
      ...item,
      createdAt: item.createdAt ? new Date(item.createdAt) : new Date(),
      updatedAt: item.updatedAt ? new Date(item.updatedAt) : new Date(),
      deletedAt: item.deletedAt ? new Date(item.deletedAt) : null,
    }));
  } catch (error) {
    console.warn(`Error parsing localStorage key "${key}":`, error);
    return [];
  }
}

function saveToStorage<T>(key: string, data: T[]): void {
  if (!isClient) return;
  try {
    localStorage.setItem(key, JSON.stringify(data));
  } catch (error) {
    console.warn(`Error saving to localStorage key "${key}":`, error);
  }
}

export class LocalTeamStorage {
  /**
   * Creates a personal team for a user
   */
  static createPersonalTeam(userId: string): LocalTeam {
    const teamId = crypto.randomUUID();
    const now = new Date();

    // Create team
    const team: LocalTeam = {
      id: teamId,
      name: "Personal",
      type: "personal",
      createdAt: now,
      updatedAt: now,
      deletedAt: null,
    };

    // Create team member
    const member: LocalTeamMember = {
      id: crypto.randomUUID(),
      teamId,
      userId,
      role: "owner",
      createdAt: now,
      updatedAt: now,
      user: LocalTeamStorage.getUserFromStorage(userId),
    };

    // Save to storage
    const teams = getFromStorage<LocalTeam>(STORAGE_KEYS.teams);
    teams.push(team);
    saveToStorage(STORAGE_KEYS.teams, teams);

    const teamMembers = getFromStorage<LocalTeamMember>(STORAGE_KEYS.teamMembers);
    teamMembers.push(member);
    saveToStorage(STORAGE_KEYS.teamMembers, teamMembers);

    return team;
  }

  /**
   * Creates a workspace team
   */
  static createTeam(userId: string, teamName: string): LocalTeam {
    const teamId = crypto.randomUUID();
    const now = new Date();

    // Create team
    const team: LocalTeam = {
      id: teamId,
      name: teamName,
      type: "workspace",
      createdAt: now,
      updatedAt: now,
      deletedAt: null,
    };

    // Create team member
    const member: LocalTeamMember = {
      id: crypto.randomUUID(),
      teamId,
      userId,
      role: "owner",
      createdAt: now,
      updatedAt: now,
      user: LocalTeamStorage.getUserFromStorage(userId),
    };

    // Save to storage
    const teams = getFromStorage<LocalTeam>(STORAGE_KEYS.teams);
    teams.push(team);
    saveToStorage(STORAGE_KEYS.teams, teams);

    const teamMembers = getFromStorage<LocalTeamMember>(STORAGE_KEYS.teamMembers);
    teamMembers.push(member);
    saveToStorage(STORAGE_KEYS.teamMembers, teamMembers);

    return team;
  }

  /**
   * Gets all teams for a user
   */
  static getUserTeams(userId: string): { team: LocalTeam; role: string }[] {
    const teams = getFromStorage<LocalTeam>(STORAGE_KEYS.teams);
    const teamMembers = getFromStorage<LocalTeamMember>(STORAGE_KEYS.teamMembers);

    // Ensure user has a personal team
    LocalTeamStorage.ensurePersonalTeam(userId);

    const userTeamMembers = teamMembers.filter((tm) => tm.userId === userId);

    return userTeamMembers
      .map((tm) => {
        const team = teams.find((t) => t.id === tm.teamId && !t.deletedAt);
        if (!team) return null;
        return { team, role: tm.role };
      })
      .filter((ut): ut is { team: LocalTeam; role: string } => ut !== null)
      .sort((a, b) => {
        // Personal team first
        if (a.team.type === "personal") return -1;
        if (b.team.type === "personal") return 1;
        // Then by creation date
        return a.team.createdAt.getTime() - b.team.createdAt.getTime();
      });
  }

  /**
   * Gets a user's personal team
   */
  static getPersonalTeam(userId: string): LocalTeam | null {
    const teams = getFromStorage<LocalTeam>(STORAGE_KEYS.teams);
    const teamMembers = getFromStorage<LocalTeamMember>(STORAGE_KEYS.teamMembers);

    const personalTeamMember = teamMembers.find((tm) => tm.userId === userId);

    if (!personalTeamMember) return null;

    const personalTeam = teams.find(
      (t) => t.id === personalTeamMember.teamId && t.type === "personal" && !t.deletedAt
    );

    return personalTeam ?? null;
  }

  /**
   * Ensures user has exactly one personal team
   */
  static ensurePersonalTeam(userId: string): LocalTeam {
    const teams = getFromStorage<LocalTeam>(STORAGE_KEYS.teams);
    const teamMembers = getFromStorage<LocalTeamMember>(STORAGE_KEYS.teamMembers);

    // Find all personal teams for user
    const userPersonalTeamIds = teamMembers
      .filter((tm) => tm.userId === userId)
      .map((tm) => tm.teamId);

    const personalTeams = teams.filter(
      (t) => userPersonalTeamIds.includes(t.id) && t.type === "personal" && !t.deletedAt
    );

    if (personalTeams.length === 0) {
      // Create personal team
      return LocalTeamStorage.createPersonalTeam(userId);
    }

    if (personalTeams.length === 1) {
      // Already has exactly one
      const team = personalTeams[0];
      if (!team) {
        throw new Error("Personal team not found");
      }
      return team;
    }

    // Multiple personal teams - keep oldest, soft delete rest
    const sortedTeams = personalTeams.sort((a, b) => a.createdAt.getTime() - b.createdAt.getTime());
    const keepTeam = sortedTeams[0];
    if (!keepTeam) {
      throw new Error("No personal team to keep");
    }
    const teamsToDelete = sortedTeams.slice(1);

    // Soft delete extra teams
    const updatedTeams = teams.map((t) => {
      if (teamsToDelete.some((td) => td.id === t.id)) {
        return { ...t, deletedAt: new Date() };
      }
      return t;
    });

    saveToStorage(STORAGE_KEYS.teams, updatedTeams);
    return keepTeam;
  }

  /**
   * Updates a team
   */
  static updateTeam(teamId: string, data: { name?: string }): LocalTeam | null {
    const teams = getFromStorage<LocalTeam>(STORAGE_KEYS.teams);
    const teamIndex = teams.findIndex((t) => t.id === teamId && !t.deletedAt);

    if (teamIndex === -1) return null;

    const existingTeam = teams[teamIndex];
    if (!existingTeam) return null;

    teams[teamIndex] = {
      ...existingTeam,
      ...data,
      updatedAt: new Date(),
    };

    saveToStorage(STORAGE_KEYS.teams, teams);
    return teams[teamIndex];
  }

  /**
   * Soft deletes a team
   */
  static deleteTeam(teamId: string): boolean {
    const teams = getFromStorage<LocalTeam>(STORAGE_KEYS.teams);
    const team = teams.find((t) => t.id === teamId);

    if (!team || team.type === "personal") {
      return false; // Cannot delete personal team
    }

    const teamIndex = teams.findIndex((t) => t.id === teamId);
    if (teamIndex === -1) return false;

    const existingTeam = teams[teamIndex];
    if (!existingTeam) return false;

    teams[teamIndex] = {
      ...existingTeam,
      deletedAt: new Date(),
    };

    saveToStorage(STORAGE_KEYS.teams, teams);
    return true;
  }

  /**
   * Adds a member to a team
   */
  static addTeamMember(teamId: string, userId: string, role: string): LocalTeamMember {
    const teamMembers = getFromStorage<LocalTeamMember>(STORAGE_KEYS.teamMembers);

    const member: LocalTeamMember = {
      id: crypto.randomUUID(),
      teamId,
      userId,
      role,
      createdAt: new Date(),
      updatedAt: new Date(),
      user: LocalTeamStorage.getUserFromStorage(userId),
    };

    teamMembers.push(member);
    saveToStorage(STORAGE_KEYS.teamMembers, teamMembers);

    return member;
  }

  /**
   * Removes a member from a team
   */
  static removeTeamMember(teamId: string, userId: string): boolean {
    const teamMembers = getFromStorage<LocalTeamMember>(STORAGE_KEYS.teamMembers);
    const filteredMembers = teamMembers.filter(
      (m) => !(m.teamId === teamId && m.userId === userId)
    );

    saveToStorage(STORAGE_KEYS.teamMembers, filteredMembers);
    return filteredMembers.length !== teamMembers.length;
  }

  /**
   * Updates a team member's role
   */
  static updateTeamMemberRole(
    teamId: string,
    userId: string,
    role: string
  ): LocalTeamMember | null {
    const teamMembers = getFromStorage<LocalTeamMember>(STORAGE_KEYS.teamMembers);
    const memberIndex = teamMembers.findIndex((m) => m.teamId === teamId && m.userId === userId);

    if (memberIndex === -1) return null;

    const existingMember = teamMembers[memberIndex];
    if (!existingMember) return null;

    teamMembers[memberIndex] = {
      ...existingMember,
      role,
      updatedAt: new Date(),
    };

    saveToStorage(STORAGE_KEYS.teamMembers, teamMembers);
    return teamMembers[memberIndex];
  }

  /**
   * Gets team members
   */
  static getTeamMembers(teamId: string): LocalTeamMember[] {
    const teamMembers = getFromStorage<LocalTeamMember>(STORAGE_KEYS.teamMembers);
    return teamMembers.filter((m) => m.teamId === teamId);
  }

  /**
   * Stores user data
   */
  static storeUser(user: LocalUser): void {
    const users = getFromStorage<LocalUser>(STORAGE_KEYS.users);
    const existingIndex = users.findIndex((u) => u.id === user.id);

    if (existingIndex !== -1) {
      users[existingIndex] = user;
    } else {
      users.push(user);
    }

    saveToStorage(STORAGE_KEYS.users, users);
  }

  /**
   * Helper to get user data from storage
   */
  private static getUserFromStorage(userId: string): {
    id: string;
    name: string | null;
    email: string;
  } {
    const users = getFromStorage<LocalUser>(STORAGE_KEYS.users);
    const user = users.find((u) => u.id === userId);

    if (user) {
      return {
        id: user.id,
        name: user.name,
        email: user.email,
      };
    }

    // Return a fallback user
    return {
      id: userId,
      name: `User ${userId.slice(0, 8)}`,
      email: `user-${userId.slice(0, 8)}@example.com`,
    };
  }

  /**
   * Initialize demo data for a user
   */
  static initializeDemoData(userId: string, userName?: string, userEmail?: string): LocalTeam {
    // Store user data
    const user: LocalUser = {
      id: userId,
      name: userName ?? `User ${userId.slice(0, 8)}`,
      email: userEmail ?? `user-${userId.slice(0, 8)}@example.com`,
      createdAt: new Date(),
      updatedAt: new Date(),
    };
    LocalTeamStorage.storeUser(user);

    // Ensure personal team exists
    return LocalTeamStorage.ensurePersonalTeam(userId);
  }

  /**
   * Clear all team data from localStorage
   */
  static clearAll(): void {
    if (!isClient) return;

    localStorage.removeItem(STORAGE_KEYS.teams);
    localStorage.removeItem(STORAGE_KEYS.teamMembers);
    localStorage.removeItem(STORAGE_KEYS.users);
  }
}

"use client";

import * as React from "react";
import { createContext, useContext, useState } from "react";

export interface TeamData {
  id: string;
  name: string;
}

interface TeamContextValue {
  teams: (TeamData & { slug: string })[];
  selectedTeamId: string | null;
  selectedTeam: (TeamData & { slug: string }) | null;
  setSelectedTeamId: (teamId: string | null) => void;
}

const TeamContext = createContext<TeamContextValue | undefined>(undefined);

interface TeamProviderProps {
  children: React.ReactNode;
  initialTeams: TeamData[];
}

export const TeamProvider = ({ children, initialTeams }: TeamProviderProps) => {
  const [teams] = useState<(TeamData & { slug: string })[]>(() =>
    (initialTeams || []).map((team) => ({
      ...team,
      slug: team.name.toLowerCase().replace(/\s+/g, "-"),
    }))
  );
  const [selectedTeamId, setSelectedTeamId] = useState<string | null>(() => {
    return initialTeams?.[0]?.id ?? null;
  });

  const selectedTeam = React.useMemo(() => {
    return teams?.find((team) => team.id === selectedTeamId) ?? null;
  }, [teams, selectedTeamId]);

  const value = React.useMemo(
    () => ({
      teams,
      selectedTeamId,
      selectedTeam,
      setSelectedTeamId,
    }),
    [teams, selectedTeamId, selectedTeam]
  );

  return <TeamContext.Provider value={value}>{children}</TeamContext.Provider>;
};

export const useTeam = () => {
  const context = useContext(TeamContext);
  if (context === undefined) {
    throw new Error("useTeam must be used within a TeamProvider");
  }
  return context;
};

import { logger } from "@/lib/logger";

export type ErrorCode =
  | "VALIDATION_ERROR"
  | "NOT_FOUND"
  | "UNAUTHORIZED"
  | "FORBIDDEN"
  | "CONFLICT"
  | "INTERNAL_SERVER_ERROR"
  | "BAD_REQUEST"
  | "RATE_LIMITED";

export interface AppError extends Error {
  code: ErrorCode;
  message: string;
  cause?: unknown;
  metadata?: Record<string, unknown>;
}

export class ErrorService {
  /**
   * Creates a standardized error object
   */
  static createError(
    code: ErrorCode,
    message: string,
    cause?: unknown,
    metadata?: Record<string, unknown>
  ): AppError {
    const error = new Error(message) as AppError;
    error.code = code;
    error.cause = cause;
    error.metadata = metadata;
    return error;
  }

  /**
   * Handles an error by logging it and returning a standardized error response
   */
  static handleError(error: unknown): AppError {
    // If it's already an AppError, just return it
    if (ErrorService.isAppError(error)) {
      logger.error(error.message, {
        code: error.code,
        cause: error.cause,
        metadata: error.metadata,
      });
      return error;
    }

    // Convert Error objects to AppError
    if (error instanceof Error) {
      const appError = ErrorService.createError("INTERNAL_SERVER_ERROR", error.message, error);
      logger.error(error.message, {
        code: appError.code,
        cause: error,
      });
      return appError;
    }

    // Handle unknown errors
    const appError = ErrorService.createError(
      "INTERNAL_SERVER_ERROR",
      "An unexpected error occurred",
      error
    );
    logger.error("Unknown error", { error });
    return appError;
  }

  /**
   * Type guard to check if an error is an AppError
   */
  static isAppError(error: unknown): error is AppError {
    return (
      error instanceof Error && "code" in error && typeof (error as AppError).code === "string"
    );
  }

  /**
   * Throws a NOT_FOUND error
   */
  static throwNotFound(message: string, metadata?: Record<string, unknown>): never {
    throw ErrorService.createError("NOT_FOUND", message, undefined, metadata);
  }

  /**
   * Throws an UNAUTHORIZED error
   */
  static throwUnauthorized(message: string, metadata?: Record<string, unknown>): never {
    throw ErrorService.createError("UNAUTHORIZED", message, undefined, metadata);
  }

  /**
   * Throws a FORBIDDEN error
   */
  static throwForbidden(message: string, metadata?: Record<string, unknown>): never {
    throw ErrorService.createError("FORBIDDEN", message, undefined, metadata);
  }

  /**
   * Throws a CONFLICT error
   */
  static throwConflict(message: string, metadata?: Record<string, unknown>): never {
    throw ErrorService.createError("CONFLICT", message, undefined, metadata);
  }

  /**
   * Throws a BAD_REQUEST error
   */
  static throwBadRequest(message: string, metadata?: Record<string, unknown>): never {
    throw ErrorService.createError("BAD_REQUEST", message, undefined, metadata);
  }

  /**
   * Throws a RATE_LIMITED error
   */
  static throwRateLimited(message: string, metadata?: Record<string, unknown>): never {
    throw ErrorService.createError("RATE_LIMITED", message, undefined, metadata);
  }
}

"use server";

import { addMinutes } from "date-fns";
import { and, eq, gt } from "drizzle-orm";
import { db } from "@/server/db";
import { temporaryLinks } from "@/server/db/schema";

const EXPIRES_IN_MINUTES = 30;

export async function createTemporaryLink({
  data,
  userId,
  type,
  expiresInMinutes = EXPIRES_IN_MINUTES,
  metadata,
}: {
  data: string;
  userId: string;
  type: string;
  expiresInMinutes?: number;
  metadata?: string;
}) {
  return await db
    ?.insert(temporaryLinks)
    .values({
      userId,
      type,
      data,
      expiresAt: addMinutes(new Date(), expiresInMinutes),
      metadata,
    })
    .returning();
}

// TODO: First use should record the IP address, and any subsequent uses from a different IP should be blocked
// TODO: Add a check to see if the link has been used already (limit uses)
export async function getTemporaryLinkData(linkId: string, userId: string) {
  const link = await db?.query.temporaryLinks.findFirst({
    where: and(
      eq(temporaryLinks.id, linkId),
      eq(temporaryLinks.userId, userId),
      gt(temporaryLinks.expiresAt, new Date())
    ),
  });

  // Reset the expiresAt if the link is used, so it can be used again
  if (link) {
    await db
      ?.update(temporaryLinks)
      .set({ expiresAt: addMinutes(new Date(), EXPIRES_IN_MINUTES) })
      .where(eq(temporaryLinks.id, linkId));
    return link.data;
  }

  return null;
}

