async function fetchTeamProjects(teamId: string): Promise<{ id: string; name: string }[]> {
  const response = await fetch(`${routes.api.projects}?teamId=${encodeURIComponent(teamId)}`);
  if (!response.ok) {
    return [];
  }
  const data = await response.json();
  return data.projects ?? [];
}

interface ProjectSwitcherProject {
  id: string;
  name: string;
}

interface ProjectSwitcherProps {
  className?: string;
  onProjectChange?: (projectId: string) => void;
}

export const ProjectSwitcher = ({ className, onProjectChange }: ProjectSwitcherProps) => {
  const { data: session } = useSession();
  const { selectedTeamId } = useTeam();

  const [projects, setProjects] = React.useState<ProjectSwitcherProject[]>([]);
  const [activeProject, setActiveProject] = React.useState<ProjectSwitcherProject | null>(null);
  const [open, setOpen] = React.useState(false);

  React.useEffect(() => {
    let isCancelled = false;

    async function loadProjects() {
      if (!selectedTeamId) {
        setProjects([]);
        setActiveProject(null);
        return;
      }

      try {
        const fetched = await fetchTeamProjects(selectedTeamId);
        if (isCancelled) return;

        const nextProjects = (fetched || []).map((p) => ({
          id: p.id,
          name: p.name,
        }));
        setProjects(nextProjects);

        // Keep selection stable across refreshes; default to first project.
        setActiveProject((previous) => {
          if (previous && nextProjects.some((p) => p.id === previous.id)) return previous;
          return nextProjects[0] ?? null;
        });
      } catch (error) {
        // No toast here yet: we don’t want a global header to spam notifications.
        // The Projects page already handles errors with UX.
        console.error("Failed to load projects:", error);
        setProjects([]);
        setActiveProject(null);
      }
    }

    void loadProjects();
    return () => {
      isCancelled = true;
    };
  }, [selectedTeamId]);

  const handleProjectSelect = React.useCallback(
    (project: ProjectSwitcherProject) => {
      setActiveProject(project);
      setOpen(false);
      onProjectChange?.(project.id);
    },
    [onProjectChange]
  );

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="ghost"
          size="sm"
          className={cn(
            "flex h-12 w-[260px] max-w-full items-center justify-between gap-2 py-6",
            className
          )}
          disabled={!selectedTeamId}
          aria-label="Select project"
        >
          <span className="truncate text-sm font-semibold">
            {activeProject?.name ?? (selectedTeamId ? "Select project" : "Select team first")}
          </span>
          <CaretSortIcon className="h-4 w-4 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-[260px] p-0" align="start">
        <Command>
          <CommandInput placeholder="Search project..." />
          <CommandList>
            <CommandEmpty>No projects found.</CommandEmpty>
            {projects.length > 0 ? (
              <>
                <CommandGroup heading="Projects">
                  {projects.map((project) => (
                    <CommandItem
                      key={project.id}
                      onSelect={() => handleProjectSelect(project)}
                      className="text-sm"
                    >
                      <span className="truncate">{project.name}</span>
                      <CheckIcon
                        className={cn(
                          "ml-auto h-4 w-4",
                          activeProject?.id === project.id ? "opacity-100" : "opacity-0"
                        )}
                      />
                    </CommandItem>
                  ))}
                </CommandGroup>
                <CommandSeparator />
              </>
            ) : (
              <CommandGroup>
                <CommandItem disabled className="text-sm text-muted-foreground">
                  No projects yet
                </CommandItem>
              </CommandGroup>
            )}
            <CommandGroup>
              {session?.user?.id ? (
                <ProjectDialog userId={session.user.id} variant="create">
                  <CommandItem onSelect={() => setOpen(false)} className="text-sm">
                    <PlusIcon className="mr-2 h-4 w-4" />
                    Create Project
                  </CommandItem>
                </ProjectDialog>
              ) : (
                <CommandItem disabled className="text-sm">
                  <PlusIcon className="mr-2 h-4 w-4" />
                  Sign in to create a project
                </CommandItem>
              )}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
};

