/**
 * The selected row's background is one element shared by every row. framer-motion's
 * layoutId makes it spring from the old row to the new one instead of blinking.
 */
const ActivePill = () => (
  <motion.span
    layoutId="sidebar-active-pill"
    aria-hidden
    className="absolute inset-0 -z-10 rounded-md bg-sidebar-accent"
    transition={{ type: "spring", stiffness: 420, damping: 32, mass: 0.8 }}
  />
);

// Helper function to determine if a route is active
const isRouteActive = (currentPath: string, itemPath: string) => {
  if (itemPath === "#") return false;
  return currentPath.startsWith(itemPath);
};

type NavItem = {
  title: string;
  url?: string;
  icon?: LucideIcon;
  /** Picks the icon's hover move in sidebar-icons.css. */
  iconName?: string;
  isActive?: boolean;
  items?: (NavItem | { title: string; url: string })[];
};

export function NavMain({ items = data }: { items?: NavItem[] }) {
  const pathname = usePathname();

  // Recursive function to render menu items
  const renderMenuItem = (item: NavItem | { title: string; url: string }) => {
    if (!pathname) return null;
    const isActive = "url" in item && item.url ? isRouteActive(pathname, item.url) : false;
    const hasActiveChild =
      "items" in item &&
      item.items?.some((subItem) =>
        "url" in subItem && subItem.url ? isRouteActive(pathname, subItem.url) : false
      );

    if (!("items" in item)) {
      return (
        <SidebarMenuItem key={item.title}>
          <SidebarMenuButton
            asChild
            tooltip={item.title}
            data-active={isActive}
            className="relative isolate active:scale-[0.98] data-[active=true]:bg-transparent data-[active=true]:hover:bg-transparent"
          >
            <Link href={item?.url ?? "#"} className="w-full max-w-full" data-icon-host>
              {isActive && <ActivePill />}
              {"icon" in item && item.icon && (
                <item.icon
                  data-icon={"iconName" in item ? item.iconName : undefined}
                  className={cn(
                    "shrink-0 text-muted-foreground transition-colors",
                    "group-hover:text-foreground",
                    isActive && "text-foreground"
                  )}
                />
              )}
              <span
                className={cn(
                  "truncate text-muted-foreground transition-colors",
                  "group-hover:text-foreground",
                  isActive && "font-medium text-foreground"
                )}
              >
                {item.title}
              </span>
            </Link>
          </SidebarMenuButton>
        </SidebarMenuItem>
      );
    }

    return (
      <Collapsible
        key={item.title}
        asChild
        defaultOpen={isActive || hasActiveChild}
        className="group/collapsible"
      >
        <SidebarMenuItem className="p-0">
          <CollapsibleTrigger asChild>
            <SidebarMenuButton
              tooltip={item.title}
              data-active={isActive || hasActiveChild}
              asChild
              className="relative isolate active:scale-[0.98] data-[active=true]:bg-transparent data-[active=true]:hover:bg-transparent"
            >
              <Link href={item?.url ?? "#"} className="w-full max-w-full" data-icon-host>
                {isActive && !hasActiveChild && <ActivePill />}
                {item.icon && (
                  <item.icon
                    data-icon={item.iconName}
                    className={cn(
                      "shrink-0 text-muted-foreground transition-colors",
                      "group-hover:text-foreground",
                      (isActive || hasActiveChild) && "text-foreground"
                    )}
                  />
                )}
                <span
                  className={cn(
                    "truncate text-muted-foreground transition-colors",
                    "group-hover:text-foreground",
                    (isActive || hasActiveChild) && "font-medium text-foreground"
                  )}
                >
                  {item.title}
                </span>
                <div className="ml-auto shrink-0 rounded-md p-1 hover:bg-muted-foreground/20">
                  <ChevronRightIcon className="transition-transform duration-200 group-data-[state=open]/collapsible:rotate-90" />
                </div>
              </Link>
            </SidebarMenuButton>
          </CollapsibleTrigger>
          <CollapsibleContent>
            <SidebarMenuSub className="mr-0 max-w-full pr-0">
              {item.items?.map((subItem) => renderMenuItem(subItem))}
            </SidebarMenuSub>
          </CollapsibleContent>
        </SidebarMenuItem>
      </Collapsible>
    );
  };

  return (
    <>
      <SidebarGroup
        className={cn(
          "relative max-w-full pl-0",
          "opacity-50 transition-opacity hover:opacity-100"
        )}
      >
        <SidebarGroupLabel className="p-0">
          <Link
            href={routes.home}
            className={cn(
              buttonVariants({ variant: "link", size: "sm" }),
              "flex w-full max-w-full items-center justify-start gap-2"
            )}
          >
            <ArrowLeftFromLineIcon className="h-4 w-4 shrink-0" />
            <span className="truncate">{siteConfig.title} Home</span>
          </Link>
        </SidebarGroupLabel>
      </SidebarGroup>

      <SidebarGroup className="max-w-full">
        <SidebarGroupLabel className="sr-only">Navigation</SidebarGroupLabel>
        <SidebarMenu className="max-w-full">
          {items.map((item) => renderMenuItem(item))}
        </SidebarMenu>
      </SidebarGroup>
    </>
  );
}

"use client";

import { UserIcon } from "lucide-react";
import { usePathname, useRouter } from "next/navigation";
import { signOut, useSession } from "@/lib/auth/use-session";
import * as React from "react";
import { toast } from "sonner";
import { UserMenuDropdown } from "@/components/modules/user/user-menu-dropdown";
import { Link } from "@/components/primitives/link";
import { useKeyboardShortcut } from "@/components/providers/keyboard-shortcut-provider";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { BorderBeam } from "@/components/ui/border-beam";
import { Button, buttonVariants } from "@/components/ui/button";
import { type Theme, useThemeToggle } from "@/components/ui/shipkit/theme";
import { ShortcutAction, type ShortcutActionType } from "@/config/keyboard-shortcuts";
import { routes } from "@/config/routes";
import { useSignInRedirectUrl } from "@/hooks/use-auth-redirect";
import { useIsAdmin } from "@/hooks/use-is-admin";
import { useSubscription } from "@/hooks/use-subscription";
import { cn } from "@/lib/utils";
import { updateTheme } from "@/server/actions/settings";
import type { User } from "@/types/user";

interface UserMenuProps {
  size?: "default" | "sm";
  className?: string;
  showUpgrade?: boolean;
  user?: User | null;
}

export const UserMenu = ({
  size = "default",
  className,
  showUpgrade = false,
  user,
}: UserMenuProps) => {
  const pathname = usePathname();
  const { data: session, status } = useSession();
  const signInRedirectUrl = useSignInRedirectUrl();
  const [isOpen, setIsOpen] = React.useState(false);
  const { hasActiveSubscription } = useSubscription();
  const router = useRouter();
  const isAdmin = useIsAdmin();

  const currentUser = user ?? session?.user;

  /*
   * Persist theme to the database when the user is logged in.
   * We do this via `useThemeToggle({ onThemeChange })` so ALL theme changes
   * (dropdown + keyboard shortcuts + animated transitions) follow one path.
   */
  const handleThemePersist = React.useCallback(
    async (newTheme: Theme) => {
      if (!currentUser) return;

      try {
        const result = await updateTheme(newTheme);
        if (!result.success) {
          toast.error("Failed to save theme preference", {
            description: result.error ?? "Your theme preference could not be saved.",
          });
        }

        toast.success("Theme updated", {
          description: result.message,
        });
      } catch (error) {
        console.error("Failed to save theme preference:", error);
        toast.error("Failed to save theme preference", {
          description: "An unexpected error occurred while saving your theme.",
        });
      }
    },
    [currentUser]
  );

  const { theme, setLightTheme, setDarkTheme, setSystemTheme } = useThemeToggle({
    onThemeChange: handleThemePersist,
  });

  // Detect invalid session state: user object exists but is missing the id field
  const isInvalidSession = React.useMemo(() => {
    if (!currentUser) return false;
    if (!currentUser.id) return true;
    return false;
  }, [currentUser]);

  // Handle invalid session by logging out and showing a toast
  React.useEffect(() => {
    if (isInvalidSession && status !== "loading") {
      // Sign out without redirect to avoid navigation loop
      void signOut({ redirect: false }).then(() => {
        toast.error("Session expired", {
          description: "Your session has expired. Would you like to sign in again?",
          action: {
            label: "Sign in",
            onClick: () => router.push(signInRedirectUrl),
          },
        });
      });
    }
  }, [isInvalidSession, status, signInRedirectUrl, router]);

  const handleThemeChange = React.useCallback(
    (value: string) => {
      const newTheme = value as Theme;
      switch (newTheme) {
        case "light":
          setLightTheme();
          break;
        case "dark":
          setDarkTheme();
          break;
        case "system":
          setSystemTheme();
          break;
      }
    },
    [setLightTheme, setDarkTheme, setSystemTheme]
  );

  // ---- Refactored Shortcut Handling ----
  const handleShortcut = React.useCallback(
    (event: KeyboardEvent, action: ShortcutActionType) => {
      event.preventDefault();
      switch (action) {
        case ShortcutAction.SET_THEME_LIGHT:
          handleThemeChange("light");
          break;
        case ShortcutAction.SET_THEME_DARK:
          handleThemeChange("dark");
          break;
        case ShortcutAction.SET_THEME_SYSTEM:
          handleThemeChange("system");
          break;
        case ShortcutAction.GOTO_ADMIN:
          if (isAdmin) router.push(routes.admin.index);
          break;
        case ShortcutAction.GOTO_SETTINGS:
          router.push(routes.settings.index);
          break;
        case ShortcutAction.LOGOUT_USER:
          void signOut({ callbackUrl: routes.home });
          break;
      }
    },
    [handleThemeChange, isAdmin, router]
  );

  const isAuthenticated = status === "authenticated";

  useKeyboardShortcut(
    ShortcutAction.SET_THEME_LIGHT,
    (event) => handleShortcut(event, ShortcutAction.SET_THEME_LIGHT),
    undefined,
    [handleShortcut]
  );
  useKeyboardShortcut(
    ShortcutAction.SET_THEME_DARK,
    (event) => handleShortcut(event, ShortcutAction.SET_THEME_DARK),
    undefined,
    [handleShortcut]
  );
  useKeyboardShortcut(
    ShortcutAction.SET_THEME_SYSTEM,
    (event) => handleShortcut(event, ShortcutAction.SET_THEME_SYSTEM),
    undefined,
    [handleShortcut]
  );
  useKeyboardShortcut(
    ShortcutAction.GOTO_ADMIN,
    (event) => handleShortcut(event, ShortcutAction.GOTO_ADMIN),
    () => isAuthenticated && isAdmin,
    [handleShortcut, isAuthenticated, isAdmin]
  );
  useKeyboardShortcut(
    ShortcutAction.GOTO_SETTINGS,
    (event) => handleShortcut(event, ShortcutAction.GOTO_SETTINGS),
    () => isAuthenticated,
    [handleShortcut, isAuthenticated]
  );
  useKeyboardShortcut(
    ShortcutAction.LOGOUT_USER,
    (event) => handleShortcut(event, ShortcutAction.LOGOUT_USER),
    () => isAuthenticated,
    [handleShortcut, isAuthenticated]
  );

  return (
    <div
      className={cn(
        "relative flex aspect-square items-center justify-center rounded-full",
        size === "sm" ? "size-9" : "size-9"
      )}
    >
      {/* Loading state */}
      {status === "loading" && (
        <BorderBeam size={size === "sm" ? 20 : 25} duration={1.5} delay={9} />
      )}

      {/* Not authenticated */}
      {currentUser ? (
        <UserMenuDropdown
          isOpen={isOpen}
          setIsOpen={setIsOpen}
          user={currentUser}
          isAdmin={isAdmin}
          showUpgrade={showUpgrade}
          hasActiveSubscription={hasActiveSubscription}
          theme={theme}
          handleThemeChange={handleThemeChange}
        >
          <Button
            variant="ghost"
            size="icon"
            className={cn("relative rounded-full", size === "sm" ? "size-6" : "size-8", className)}
            aria-label="User menu"
          >
            <Avatar className={cn(size === "sm" ? "size-6" : "size-8")}>
              <AvatarImage
                src={currentUser?.image ?? ""}
                alt={currentUser?.name ?? "User avatar"}
                draggable={false}
              />
              <AvatarFallback>{currentUser?.name?.[0]?.toUpperCase() ?? "?"}</AvatarFallback>
            </Avatar>
          </Button>
        </UserMenuDropdown>
      ) : pathname !== routes.auth.signIn && pathname !== routes.auth.signUp ? (
        <Link
          href={signInRedirectUrl}
          className={cn(
            buttonVariants({ variant: "ghost", size: "icon" }),
            "cursor-pointer rounded-full"
          )}
        >
          <UserIcon className="size-4" />
        </Link>
      ) : (
        <Button variant="ghost" size="icon" className={cn("relative rounded-full", className)}>
          <UserIcon className="size-4" />
        </Button>
      )}
    </div>
  );
};

