/**
 * evlog trial feature flag (LAC-3361).
 *
 * evlog is young (single maintainer, ~7 months old), so it is opt-in and must
 * never become load-bearing: everything evlog-related checks this flag first,
 * and rip-out is deleting this file plus its call sites.
 *
 * This module is imported from isomorphic code (logger), so it cannot import
 * features-config.ts — that file's env mirroring side effects must stay out of
 * the client bundle. The flag re-implements the same truthy check instead.
 */

const TRUTHY_FLAG_VALUES = ["true", "1", "yes", "on", "enable", "enabled"];

/**
 * Whether the evlog trial is enabled. Always false in the browser — the trial
 * covers server-side logging, request-error capture, and audit events only.
 */
export function isEvlogEnabled(): boolean {
  if (typeof window !== "undefined") return false;
  const value = process.env.ENABLE_EVLOG ?? process.env.NEXT_PUBLIC_FEATURE_EVLOG_ENABLED ?? "";
  return TRUTHY_FLAG_VALUES.includes(value.toLowerCase().trim());
}

"use server";

/**
 * @fileoverview Server actions for temporary link operations (mutations only)
 * NOTE: For read operations, use the service directly:
 * import { getTemporaryLinkData } from "@/server/services/temporary-links"
 */

import { createTemporaryLink } from "@/server/services/temporary-links";

/**
 * Generates a temporary download link for a user
 */
export const generateTemporaryLink = async ({
  data = "hello",
  userId,
}: {
  data?: string;
  userId: string;
}) => {
  const link = await createTemporaryLink({ data, userId, type: "download" });
  if (!link || link.length === 0 || !link[0]) {
    throw new Error("Failed to create temporary link");
  }
  return link[0].id;
};

/**
 * Audit logging for entity changes (evlog trial, LAC-3361).
 *
 * Emits tamper-evident, redaction-aware audit events via evlog. Every helper
 * is a no-op while the trial flag is off, and recordAudit never throws — audit
 * logging must never take down the mutation it observes.
 *
 * Events land in the same pipeline as the rest of evlog output (console +
 * whatever drain instrumentation.ts configured, e.g. OTLP).
 */

import { type AuditActor, type AuditInput, audit, defineAuditAction } from "evlog";
import { isEvlogEnabled } from "@/lib/evlog";

/**
 * Catalog of audit actions. defineAuditAction pre-fills the action name and
 * target type so call sites stay terse and the action set is discoverable in
 * one place. Extend here when auditing new entities (users, billing, …).
 */
export const auditAction = {
  teamCreate: defineAuditAction("team.create", { target: "team" }),
  teamUpdate: defineAuditAction("team.update", { target: "team" }),
  teamDelete: defineAuditAction("team.delete", { target: "team", severity: "high" }),
  teamMemberAdd: defineAuditAction("team.member.add", { target: "team" }),
  teamMemberRemove: defineAuditAction("team.member.remove", { target: "team" }),
  teamMemberRoleUpdate: defineAuditAction("team.member.role_update", { target: "team" }),
};

/** Actor for mutations that cannot be attributed to a signed-in user. */
export const systemActor: AuditActor = { type: "system", id: "shipkit" };

export function userActor(id: string): AuditActor {
  return { type: "user", id };
}

/**
 * Resolve the acting user from the current session, falling back to the
 * system actor. Skips the session lookup entirely while the trial is off.
 */
export async function resolveSessionActor(): Promise<AuditActor> {
  if (!isEvlogEnabled()) return systemActor;
  try {
    const { auth } = await import("@/server/auth");
    const session = await auth();
    return session?.user?.id ? userActor(session.user.id) : systemActor;
  } catch {
    return systemActor;
  }
}

/**
 * Emit an audit event. No-op while the trial flag is off; swallows emit
 * errors so callers never fail because of observability.
 */
export function recordAudit(input: AuditInput): void {
  if (!isEvlogEnabled()) return;
  try {
    audit(input);
  } catch (error) {
    console.warn("[audit-service] failed to record audit event", error);
  }
}

import { z } from "zod";
import { logger } from "@/lib/logger";

export interface ValidationError {
  code: "VALIDATION_ERROR";
  message: string;
  fieldErrors?: Record<string, string[]>;
}

export interface ValidationResult<T> {
  success: boolean;
  data?: T;
  error?: ValidationError;
}

export class ValidationService {
  /**
   * Validates data against a schema and returns a strongly typed result
   */
  static async validate<T>(schema: z.ZodType<T>, data: unknown): Promise<ValidationResult<T>> {
    try {
      const validatedData = await schema.parseAsync(data);
      return {
        success: true,
        data: validatedData,
      };
    } catch (error) {
      if (error instanceof z.ZodError) {
        const fieldErrors = Object.entries(error.formErrors.fieldErrors).reduce(
          (acc, [key, value]) => {
            if (value) {
              acc[key] = Array.isArray(value) ? value.filter(Boolean) : [value];
            }
            return acc;
          },
          {} as Record<string, string[]>
        );

        logger.error("Validation error", { error: fieldErrors });

        return {
          success: false,
          error: {
            code: "VALIDATION_ERROR",
            message: "Validation failed",
            fieldErrors,
          },
        };
      }

      logger.error("Unexpected validation error", { error });

      return {
        success: false,
        error: {
          code: "VALIDATION_ERROR",
          message: "An unexpected validation error occurred",
        },
      };
    }
  }

  /**
   * Validates data and throws an error if validation fails
   */
  static async validateOrThrow<T>(schema: z.ZodType<T>, data: unknown): Promise<T> {
    const result = await ValidationService.validate(schema, data);
    if (!result.success) {
      const errorInfo = result.error;
      const validationError = new Error(errorInfo?.message ?? "Validation failed");
      if (errorInfo) {
        Object.assign(validationError, errorInfo);
      }
      throw validationError;
    }
    return result.data as T;
  }
}

export const validationService = new ValidationService();

